import React,{useState} from 'react';
import {createRoot} from 'react-dom/client';
import EchoLivingLightCueEditor from '../../src/components/EchoLivingLightCueEditor.jsx';
const make=(id,title)=>({journeyId:id,revisionId:'revision:one',title,songId:'fixture:song',sourceBindingRef:null,schedule:[{instanceId:'location-a',startUs:0,endUs:6e6},{instanceId:'bridge',startUs:6e6,endUs:14e6,fromInstanceId:'location-a',toInstanceId:'location-b'},{instanceId:'location-b',startUs:14e6,endUs:20e6}]});
const journeys=[make('journey:solar','Solar Reliquary → Tidal Observatory'),make('journey:resonance','Resonance Vault → Lumen Arcade')];
const client={request:async route=>{if(route.startsWith('/journeys?'))return {journeys:journeys.map(journey=>({journey})),nextOffset:null};const id=decodeURIComponent(route.split('/')[2]);const journey=journeys.find(j=>j.journeyId===id);if(!journey)throw Error('Missing fixture revision');return {journey};}};
function Study(){const [project,setProject]=useState({song_id:'fixture:song',song_title:'Director cue study',duration:30,living_light_cues:[],timeline:[{media_id:'existing-clip'}]});return <main style={{maxWidth:1000,margin:'24px auto',padding:12}}><h2>Living Light · Director scenes</h2><p>Isolated editor study. These two fixture Journeys never write album data.</p><EchoLivingLightCueEditor project={project} cutKey="fixture-cut" currentTime={2} client={client} onChange={cues=>setProject(p=>({...p,living_light_cues:cues}))}/><button onClick={()=>setProject(p=>({...p,timeline:[{media_id:'another-clip'}]}))}>Change unrelated media</button><details><summary>Cut draft</summary><pre data-testid="cue-study-draft">{JSON.stringify(project,null,2)}</pre></details></main>;}
const root=createRoot(document.getElementById('root'));root.render(<Study/>);if(import.meta.hot)import.meta.hot.dispose(()=>root.unmount());
